export async function withDatabaseRetry<T>(operation: () => Promise<T>, attempts = 3): Promise<T> {
  try { return await operation(); }
  catch (error) { if (attempts <= 1) throw error; return withDatabaseRetry(operation, attempts - 1); }
}

